import { PropsWithChildren } from 'react';

import { EmptyStateSlot } from '../../core/slots/chart-states/EmptyStateSlot.js';
import { ErrorStateSlot } from '../../core/slots/chart-states/ErrorStateSlot.js';
import { Threshold } from '../../sparkline/slots/Threshold.js';
import { YAxis } from '../../sparkline/slots/YAxis.js';
import type { SparklineProps } from '../../sparkline/Sparkline.js';

/** Slot props for the Sparkline component within SingleValue. */
export type SingleValueSparklineProps = PropsWithChildren<
  Omit<SparklineProps, 'loading'>
>;
const SparklineRoot = (props: PropsWithChildren<SingleValueSparklineProps>) =>
  null;

/** Slot for the Sparkline component */
export const Sparkline = Object.assign(SparklineRoot, {
  Threshold,
  YAxis,
  EmptyState: EmptyStateSlot,
  ErrorState: ErrorStateSlot,
});

(Sparkline as typeof Sparkline & { displayName: string }).displayName =
  'SingleValue.Sparkline';
